      if (this.listenerToAbortCleanup.get(listener)?.has(type)) return;

      const abortHandler = () => {
        this.off(type, listener);
        const typeToCleanup = this.listenerToAbortCleanup.get(listener);
        if (typeToCleanup) {
          typeToCleanup.delete(type);
