    const typeToCleanup = this.listenerToAbortCleanup.get(listener);
    if (typeToCleanup) {
      const cleanup = typeToCleanup.get(type);
      if (cleanup) {
        cleanup();
        typeToCleanup.delete(type);
      }
      if (typeToCleanup.size === 0) {
        this.listenerToAbortCleanup.delete(listener);
      }
    }
  }

